use core::arch::wasm32::memory_size;
use core::cell::UnsafeCell;
use core::ptr::addr_of;

mod lzw;
mod mapper;
mod palette;

use lzw::{encode_lzw, LzwError, LzwScratch};

use mapper::{map_in_place, MapperScratch};
use palette::{build_palette, PaletteMethod, PaletteScratch};

const PAGE_BYTES: usize = 65_536;
const MAX_RETAINED_GENERATION: u32 = (i32::MAX as u32) >> 2;
const BAYER_8X8: [i16; 64] = [
    0, 32, 8, 40, 2, 34, 10, 42, 48, 16, 56, 24, 50, 18, 58, 26, 12, 44, 4, 36, 14, 46, 6, 38, 60,
    28, 52, 20, 62, 30, 54, 22, 3, 35, 11, 43, 1, 33, 9, 41, 51, 19, 59, 27, 49, 17, 57, 25, 15,
    47, 7, 39, 13, 45, 5, 37, 63, 31, 55, 23, 61, 29, 53, 21,
];

#[derive(Clone, Copy)]
struct RetainedSlot {
    palette: [u8; 256 * 3],
    palette_len: u16,
    hash: i32,
    generation: u32,
    live: bool,
}

impl RetainedSlot {
    const EMPTY: Self = Self {
        palette: [0; 256 * 3],
        palette_len: 0,
        hash: 0,
        generation: 0,
        live: false,
    };
}

#[repr(C)]
struct RetainedResult {
    status: i32,
    handle: u32,
}

impl RetainedResult {
    const EMPTY: Self = Self {
        status: 0,
        handle: 0,
    };
}

struct State {
    scratch: PaletteScratch,
    mapper: MapperScratch,
    lzw: LzwScratch,
    palette: [u8; 256 * 3],
    reserved_input_len: u32,
    input_was_mapped: bool,
    input_prepared: bool,
    retained: [RetainedSlot; 3],
    retained_len: u32,
    retained_enabled: bool,
    generation: u32,
    global_palette: [u8; 256 * 3],
    global_len: u16,
    retained_result: RetainedResult,
}

struct ConversionState(UnsafeCell<State>);

// Each GIF conversion instantiates its own module and calls it serially, in
// the usual Worker route or the existing main-thread fallback. No threads,
// shared memory or references into State escape the ABI.
unsafe impl Sync for ConversionState {}

static STATE: ConversionState = ConversionState(UnsafeCell::new(State {
    scratch: PaletteScratch::EMPTY,
    mapper: MapperScratch::EMPTY,
    lzw: LzwScratch::EMPTY,
    palette: [0; 256 * 3],
    reserved_input_len: 0,
    input_was_mapped: false,
    input_prepared: false,
    retained: [RetainedSlot::EMPTY; 3],
    retained_len: 0,
    retained_enabled: false,
    generation: 0,
    global_palette: [0; 256 * 3],
    global_len: 0,
    retained_result: RetainedResult::EMPTY,
}));

#[no_mangle]
pub extern "C" fn abi_version() -> u32 {
    3
}

extern "C" {
    static __heap_base: u8;
}

#[inline]
fn input_start() -> usize {
    addr_of!(__heap_base) as usize
}

#[no_mangle]
pub extern "C" fn input_ptr() -> u32 {
    input_start() as u32
}

#[no_mangle]
pub extern "C" fn palette_ptr() -> u32 {
    unsafe { (*STATE.0.get()).palette.as_ptr() as u32 }
}

// JS grows memory after charging both old and new capacities to the existing
// Worker guard. This function checks that capacity; Rust never allocates input.
#[no_mangle]
pub extern "C" fn reserve_input(input_len: u32) -> i32 {
    let len = input_len as usize;
    if len == 0 || (len & 3) != 0 {
        return -1;
    }
    let Some(end) = input_start().checked_add(len) else {
        return -1;
    };
    if end > memory_size::<0>() * PAGE_BYTES {
        return -2;
    }
    let state = unsafe { &mut *STATE.0.get() };
    if state.retained_enabled && (state.retained_len != input_len || state.retained[0].live) {
        return -1;
    }
    state.reserved_input_len = input_len;
    state.input_was_mapped = false;
    state.input_prepared = false;
    0
}

fn retained_end(input_len: u32) -> Option<usize> {
    if input_len == 0 || (input_len & 3) != 0 {
        return None;
    }
    let pixels = (input_len / 4) as usize;
    retained_ptr(2, pixels)?.checked_add(pixels)
}

#[no_mangle]
pub extern "C" fn retained_layout_end(input_len: u32) -> u32 {
    retained_end(input_len)
        .and_then(|end| u32::try_from(end).ok())
        .unwrap_or(0)
}

#[no_mangle]
pub extern "C" fn enable_retained(input_len: u32) -> i32 {
    let Some(end) = retained_end(input_len) else {
        return -1;
    };
    if end > u32::MAX as usize {
        return -1;
    }
    if end > memory_size::<0>() * PAGE_BYTES {
        return -2;
    }
    let state = unsafe { &mut *STATE.0.get() };
    if state.retained_enabled
        || state.reserved_input_len != 0
        || state.retained.iter().any(|slot| slot.live)
    {
        return -1;
    }
    state.retained_len = input_len;
    state.retained_enabled = true;
    0
}

#[inline]
fn retained_ptr(slot: usize, pixels: usize) -> Option<usize> {
    match slot {
        0 => Some(input_start()),
        1 | 2 => {
            // For tiny frames the conservative LZW bound can extend past the
            // 4N RGBA arena. Keep both protected slots beyond that bound.
            let rgba_end = pixels.checked_mul(4)?;
            let image_end = pixels.checked_add(image_data_bound(u32::try_from(pixels).ok()?)?)?;
            input_start()
                .checked_add(rgba_end.max(image_end))?
                .checked_add(pixels.checked_mul(slot - 1)?)
        }
        _ => None,
    }
}

#[inline]
fn checked_slot(state: &State, handle: u32) -> Option<usize> {
    let slot = (handle & 3) as usize;
    let generation = handle >> 2;
    if slot < 3 && generation != 0 {
        let entry = &state.retained[slot];
        if entry.live && entry.generation == generation {
            return Some(slot);
        }
    }
    None
}

fn fresh_handle(state: &mut State, slot: usize) -> Option<u32> {
    if state.generation >= MAX_RETAINED_GENERATION {
        return None;
    }
    state.generation += 1;
    state.retained[slot].generation = state.generation;
    state.retained[slot].live = true;
    Some((state.generation << 2) | slot as u32)
}

#[inline]
fn record_retained_result(state: &mut State, status: i32, handle: u32) -> i32 {
    state.retained_result = RetainedResult {
        status,
        handle: if status == 0 { handle } else { 0 },
    };
    status
}

#[no_mangle]
pub extern "C" fn retained_result_ptr() -> u32 {
    unsafe { core::ptr::addr_of!((*STATE.0.get()).retained_result) as u32 }
}

// Apply the locked JS 8x8 Bayer threshold after the host has made its one
// admitted RGBA copy. Signed integer division truncates toward zero, matching
// the Int8 LUT's `(value * strength / 64) | 0` for every supported strength.
#[no_mangle]
pub extern "C" fn prepare_rgba(input_len: u32, width: u32, height: u32, strength: u32) -> i32 {
    if input_len == 0
        || input_len as usize > isize::MAX as usize
        || width == 0
        || height == 0
        || strength > 255
    {
        return -1;
    }
    let Some(pixels) = width.checked_mul(height) else {
        return -1;
    };
    if pixels.checked_mul(4) != Some(input_len) {
        return -1;
    }
    let state = unsafe { &mut *STATE.0.get() };
    if state.reserved_input_len != input_len || state.input_was_mapped || state.input_prepared {
        return -1;
    }
    let Some(end) = input_start().checked_add(input_len as usize) else {
        return -1;
    };
    if end > memory_size::<0>() * PAGE_BYTES {
        return -2;
    }
    // The input arena begins at __heap_base and is disjoint from static State.
    // No input borrow survives this synchronous ABI call.
    let rgba =
        unsafe { core::slice::from_raw_parts_mut(input_start() as *mut u8, input_len as usize) };
    if strength != 0 {
        let offsets = BAYER_8X8.map(|b| (i32::from(b - 32) * strength as i32) / 64);
        for (y, row) in rgba.chunks_exact_mut(width as usize * 4).enumerate() {
            let phases = &offsets[(y & 7) * 8..(y & 7) * 8 + 8];
            for block in row.chunks_mut(8 * 4) {
                for (px, &delta) in block.as_chunks_mut::<4>().0.iter_mut().zip(phases) {
                    if delta != 0 {
                        for c in &mut px[..3] {
                            *c = (i32::from(*c) + delta).clamp(0, 255) as u8;
                        }
                    }
                }
            }
        }
    }
    state.input_prepared = true;
    0
}

#[no_mangle]
pub extern "C" fn quantize(input_len: u32, colors: u32) -> i32 {
    if input_len == 0 || (input_len & 3) != 0 || !(1..=256).contains(&colors) {
        return -1;
    }
    let state = unsafe { &mut *STATE.0.get() };
    if state.reserved_input_len != input_len || state.input_was_mapped {
        return -1;
    }
    let Some(end) = input_start().checked_add(input_len as usize) else {
        return -1;
    };
    if end > memory_size::<0>() * PAGE_BYTES {
        return -2;
    }
    // The caller owns this disjoint region from __heap_base through end.
    let rgba =
        unsafe { core::slice::from_raw_parts(input_start() as *const u8, input_len as usize) };
    build_palette(
        rgba,
        colors as usize,
        &mut state.palette,
        &mut state.scratch,
        PaletteMethod::Variance,
    )
    .map_or(-1, |count| count as i32)
}

#[inline]
fn indexed_start() -> usize {
    input_start()
}

#[no_mangle]
pub extern "C" fn indices_ptr() -> u32 {
    indexed_start() as u32
}

// The fixed-palette ABI caches the first pixel in each five-bit R/G/B cell.
// Preserve its green mask and last-index tie rule on both mapping paths.
#[no_mangle]
pub extern "C" fn map_palette(input_len: u32, colors: u32) -> i32 {
    if input_len == 0 || (input_len & 3) != 0 || !(1..=256).contains(&colors) {
        return -1;
    }
    let state = unsafe { &mut *STATE.0.get() };
    if state.reserved_input_len != input_len || state.input_was_mapped {
        return -1;
    }
    let start = indexed_start();
    let Some(end) = input_start().checked_add(input_len as usize) else {
        return -1;
    };
    if end > u32::MAX as usize {
        return -1;
    }
    if end > memory_size::<0>() * PAGE_BYTES {
        return -2;
    }

    // reserve_input validated the caller-owned arena. Its unique mutable view is
    // disjoint from the palette and static mapper scratch and ends inside this call.
    let rgba = unsafe { core::slice::from_raw_parts_mut(start as *mut u8, input_len as usize) };
    let Some(count) = map_in_place(
        rgba,
        &state.palette[..colors as usize * 3],
        &mut state.mapper,
    ) else {
        return -1;
    };
    state.input_was_mapped = true;
    count as i32
}

// The mapped indexes still occupy the first N bytes of the RGBA arena. Keep
// this transient candidate until the host either discards it or promotes it
// into one of two protected slots before admitting the next input frame.
#[no_mangle]
pub extern "C" fn map_retained(input_len: u32, colors: u32) -> i32 {
    {
        let state = unsafe { &mut *STATE.0.get() };
        state.retained_result = RetainedResult::EMPTY;
        if !state.retained_enabled || state.retained_len != input_len || state.retained[0].live {
            return record_retained_result(state, -1, 0);
        }
        if state.generation >= MAX_RETAINED_GENERATION {
            return record_retained_result(state, -1, 0);
        }
    }
    let mapped = map_palette(input_len, colors);
    if mapped < 0 {
        return record_retained_result(unsafe { &mut *STATE.0.get() }, mapped, 0);
    }
    let state = unsafe { &mut *STATE.0.get() };
    let count = mapped as usize;
    let mut compact = [0u8; 256 * 3];
    let mut compact_len = 0usize;
    let mut old_to_new = [u16::MAX; 256];
    let mut hash = 0x811c9dc5u32;
    for pixel in 0..count {
        let pointer = input_start() + pixel;
        let old_index = unsafe { *(pointer as *const u8) } as usize;
        if old_index >= colors as usize {
            return record_retained_result(state, -3, 0);
        }
        let color = &state.palette[old_index * 3..old_index * 3 + 3];
        let packed = ((color[0] as u32) << 16) | ((color[1] as u32) << 8) | color[2] as u32;
        let mut new_index = old_to_new[old_index];
        if new_index == u16::MAX {
            new_index = (0..compact_len)
                .find(|&index| compact[index * 3..index * 3 + 3] == *color)
                .map(|index| index as u16)
                .unwrap_or_else(|| {
                    let index = compact_len;
                    compact[index * 3..index * 3 + 3].copy_from_slice(color);
                    compact_len += 1;
                    index as u16
                });
            old_to_new[old_index] = new_index;
        }
        unsafe { *(pointer as *mut u8) = new_index as u8 };
        hash = (hash ^ packed).wrapping_mul(0x0100_0193);
    }
    state.retained[0].palette = compact;
    state.retained[0].palette_len = compact_len as u16;
    state.retained[0].hash = hash as i32;
    match fresh_handle(state, 0) {
        Some(handle) => record_retained_result(state, 0, handle),
        None => record_retained_result(state, -1, 0),
    }
}

#[no_mangle]
pub extern "C" fn promote_retained(handle: u32) -> i32 {
    let state = unsafe { &mut *STATE.0.get() };
    state.retained_result = RetainedResult::EMPTY;
    if checked_slot(state, handle) != Some(0) || !state.retained_enabled {
        return record_retained_result(state, -1, 0);
    }
    let Some(slot) = (1..=2).find(|&slot| !state.retained[slot].live) else {
        return record_retained_result(state, -2, 0);
    };
    if state.generation >= MAX_RETAINED_GENERATION {
        return record_retained_result(state, -1, 0);
    }
    let pixels = (state.retained_len / 4) as usize;
    let Some(end) = retained_ptr(slot, pixels).and_then(|start| start.checked_add(pixels)) else {
        return record_retained_result(state, -1, 0);
    };
    if end > memory_size::<0>() * PAGE_BYTES {
        return record_retained_result(state, -2, 0);
    }
    unsafe {
        core::ptr::copy_nonoverlapping(
            input_start() as *const u8,
            retained_ptr(slot, pixels).unwrap() as *mut u8,
            pixels,
        );
    }
    state.retained[slot] = state.retained[0];
    state.retained[0].live = false;
    match fresh_handle(state, slot) {
        Some(handle) => record_retained_result(state, 0, handle),
        None => record_retained_result(state, -1, 0),
    }
}

#[no_mangle]
pub extern "C" fn release_retained(handle: u32) -> i32 {
    let state = unsafe { &mut *STATE.0.get() };
    let Some(slot) = checked_slot(state, handle) else {
        return -1;
    };
    state.retained[slot].live = false;
    0
}

#[no_mangle]
pub extern "C" fn retained_palette_len(handle: u32) -> i32 {
    let state = unsafe { &*STATE.0.get() };
    checked_slot(state, handle)
        .map(|slot| state.retained[slot].palette_len as i32)
        .unwrap_or(-1)
}

#[no_mangle]
pub extern "C" fn retained_palette_ptr(handle: u32) -> u32 {
    let state = unsafe { &*STATE.0.get() };
    checked_slot(state, handle)
        .map(|slot| state.retained[slot].palette.as_ptr() as u32)
        .unwrap_or(0)
}

#[no_mangle]
pub extern "C" fn retained_hash(handle: u32) -> i32 {
    let state = unsafe { &*STATE.0.get() };
    checked_slot(state, handle)
        .map(|slot| state.retained[slot].hash)
        .unwrap_or(0)
}

#[no_mangle]
pub extern "C" fn same_retained_pixels(first: u32, second: u32) -> i32 {
    let state = unsafe { &*STATE.0.get() };
    let (Some(a), Some(b)) = (checked_slot(state, first), checked_slot(state, second)) else {
        return -1;
    };
    if state.retained[a].hash != state.retained[b].hash {
        return 0;
    }
    let pixels = (state.retained_len / 4) as usize;
    let (Some(a_ptr), Some(b_ptr)) = (retained_ptr(a, pixels), retained_ptr(b, pixels)) else {
        return -1;
    };
    for pixel in 0..pixels {
        let a_index = unsafe { *((a_ptr + pixel) as *const u8) } as usize;
        let b_index = unsafe { *((b_ptr + pixel) as *const u8) } as usize;
        if a_index >= state.retained[a].palette_len as usize
            || b_index >= state.retained[b].palette_len as usize
        {
            return -1;
        }
        if state.retained[a].palette[a_index * 3..a_index * 3 + 3]
            != state.retained[b].palette[b_index * 3..b_index * 3 + 3]
        {
            return 0;
        }
    }
    1
}

fn palette_depth(len: usize) -> u32 {
    (usize::BITS - (len.max(2) - 1).leading_zeros()).max(2)
}

#[no_mangle]
pub extern "C" fn capture_global_palette(handle: u32) -> i32 {
    let state = unsafe { &mut *STATE.0.get() };
    let Some(slot) = checked_slot(state, handle) else {
        return -1;
    };
    if state.global_len != 0 {
        return -1;
    }
    state.global_len = state.retained[slot].palette_len;
    state.global_palette = state.retained[slot].palette;
    0
}

#[no_mangle]
pub extern "C" fn remap_retained_global(handle: u32) -> i32 {
    let state = unsafe { &mut *STATE.0.get() };
    let Some(slot) = checked_slot(state, handle) else {
        return -1;
    };
    let local_len = state.retained[slot].palette_len as usize;
    let global_len = state.global_len as usize;
    if slot == 0 || global_len == 0 || palette_depth(local_len) != palette_depth(global_len) {
        return 0;
    }
    let mut remap = [0u8; 256];
    for (local, target) in remap.iter_mut().enumerate().take(local_len) {
        let color = &state.retained[slot].palette[local * 3..local * 3 + 3];
        let Some(global) =
            (0..global_len).find(|&index| state.global_palette[index * 3..index * 3 + 3] == *color)
        else {
            return 0;
        };
        *target = global as u8;
    }
    let pixels = (state.retained_len / 4) as usize;
    let Some(pointer) = retained_ptr(slot, pixels) else {
        return -1;
    };
    for pixel in 0..pixels {
        let old = unsafe { *((pointer + pixel) as *const u8) } as usize;
        if old >= local_len {
            return -1;
        }
        unsafe { *((pointer + pixel) as *mut u8) = remap[old] };
    }
    // The frame now references the global palette. Its expanded colors and
    // pre-remap FNV hash remain identical.
    state.retained[slot].palette = state.global_palette;
    state.retained[slot].palette_len = state.global_len;
    1
}

fn image_data_bound(pixel_count: u32) -> Option<usize> {
    if pixel_count == 0 {
        return None;
    }
    let pixels = pixel_count as usize;
    // Every input pixel produces at most one ordinary code. A full table can
    // cause one extra clear only after at least 3838 misses (depth 8 is the
    // worst case). All codes fit in 12 bits. Count packet sizes separately.
    let clears = pixels.checked_add(3837)?.checked_div(3838)?;
    let codes = pixels.checked_add(clears)?.checked_add(3)?;
    let packed = codes.checked_mul(12)?.checked_add(7)?.checked_div(8)?;
    let blocks = packed.checked_add(253)?.checked_div(254)?;
    packed.checked_add(blocks)?.checked_add(2)
}

#[no_mangle]
pub extern "C" fn lzw_bound(pixel_count: u32) -> u32 {
    image_data_bound(pixel_count)
        .and_then(|bound| u32::try_from(bound).ok())
        .unwrap_or(0)
}

fn image_data_start(input_len: usize) -> Option<usize> {
    input_start().checked_add(input_len / 4)
}

#[no_mangle]
pub extern "C" fn lzw_output_ptr() -> u32 {
    let input_len = unsafe { (*STATE.0.get()).reserved_input_len as usize };
    image_data_start(input_len)
        .and_then(|start| u32::try_from(start).ok())
        .unwrap_or(0)
}

#[no_mangle]
pub extern "C" fn lzw_encode(pixel_count: u32, depth: u32, output_capacity: u32) -> i32 {
    let state = unsafe { &*STATE.0.get() };
    let input_len = state.reserved_input_len as usize;
    if input_len == 0 || (input_len & 3) != 0 || pixel_count as usize != input_len / 4 {
        return -1;
    }
    lzw_encode_from(indexed_start(), pixel_count, depth, output_capacity)
}

#[no_mangle]
pub extern "C" fn lzw_encode_retained(handle: u32, depth: u32, output_capacity: u32) -> i32 {
    let state = unsafe { &*STATE.0.get() };
    let Some(slot) = checked_slot(state, handle) else {
        return -1;
    };
    if !state.retained_enabled || slot == 0 || state.reserved_input_len != state.retained_len {
        return -1;
    }
    let pixels = state.retained_len / 4;
    let bound = lzw_bound(pixels);
    if bound == 0 || output_capacity > bound {
        return -1;
    }
    let Some(pointer) = retained_ptr(slot, pixels as usize) else {
        return -1;
    };
    lzw_encode_from(pointer, pixels, depth, output_capacity)
}

fn lzw_encode_from(index_start: usize, pixel_count: u32, depth: u32, output_capacity: u32) -> i32 {
    if pixel_count == 0 || !(2..=8).contains(&depth) || output_capacity == 0 {
        return -1;
    }
    let state = unsafe { &mut *STATE.0.get() };
    let input_len = state.reserved_input_len as usize;
    let Some(index_end) = index_start.checked_add(pixel_count as usize) else {
        return -1;
    };
    let Some(output_start) = image_data_start(input_len) else {
        return -1;
    };
    let Some(output_end) = output_start.checked_add(output_capacity as usize) else {
        return -1;
    };
    if output_end > u32::MAX as usize || (output_start < index_end && output_end > index_start) {
        return -1;
    }
    if index_end > memory_size::<0>() * PAGE_BYTES || output_end > memory_size::<0>() * PAGE_BYTES {
        return -2;
    }
    // No reference to these disjoint ABI ranges escapes this synchronous call.
    let indices =
        unsafe { core::slice::from_raw_parts(index_start as *const u8, pixel_count as usize) };
    let output = unsafe {
        core::slice::from_raw_parts_mut(output_start as *mut u8, output_capacity as usize)
    };
    match encode_lzw(indices, depth as u8, output, &mut state.lzw) {
        Ok(length) => length as i32,
        Err(LzwError::InvalidDepth | LzwError::InvalidIndex) => -1,
        Err(LzwError::OutputTooSmall) => -2,
    }
}

//! GIF image data blocks for an already mapped frame.

const CODE_LIMIT: u16 = 4096;
const MAX_CODE_WIDTH: u8 = 12;
const SLOT_COUNT: usize = 8192;
const KEY_BITS: u32 = 20;
const KEY_MASK: u32 = (1 << KEY_BITS) - 1;
const BLOCK_LIMIT: u8 = 254;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum LzwError {
    InvalidDepth,
    InvalidIndex,
    OutputTooSmall,
}

/// Reusable fixed storage. Initialize directly in caller-owned static memory
/// with `LzwScratch::EMPTY`.
pub struct LzwScratch {
    slots: [u32; SLOT_COUNT],
}

impl LzwScratch {
    pub const EMPTY: Self = Self {
        slots: [0; SLOT_COUNT],
    };

    fn reset(&mut self) {
        self.slots.fill(0);
    }

    fn lookup(&self, key: u32) -> (usize, u32) {
        let hash = key.wrapping_mul(0x9e37_79b1);
        let mut slot = (hash >> (u32::BITS - SLOT_COUNT.trailing_zeros())) as usize;
        loop {
            let entry = self.slots[slot];
            if entry == 0 || entry & KEY_MASK == key {
                return (slot, entry);
            }
            slot = (slot + 1) & (SLOT_COUNT - 1);
        }
    }
}

/// Writes the minimum code size, GIF LZW sub-blocks and zero terminator.
///
/// Accepts depths 2 through 8 and indices below 2 to the power of depth.
/// Empty input produces a clear code followed by an end code. Invalid depth
/// or indices leave output untouched. On insufficient capacity, the output
/// prefix may have been written. Success returns the exact length and leaves
/// the remaining output unchanged.
pub fn encode_lzw(
    indices: &[u8],
    depth: u8,
    output: &mut [u8],
    scratch: &mut LzwScratch,
) -> Result<usize, LzwError> {
    if !(2..=8).contains(&depth) {
        return Err(LzwError::InvalidDepth);
    }

    let clear = 1_u16 << depth;
    if depth < 8 && indices.iter().any(|&index| u16::from(index) >= clear) {
        return Err(LzwError::InvalidIndex);
    }

    let mut writer = SubBlocks::new(output);
    writer.byte(depth)?;

    let mut width = depth + 1;
    writer.code(clear, width)?;
    if let Some((&first, remaining)) = indices.split_first() {
        scratch.reset();
        let mut next_code = clear + 2;
        let mut prefix = u16::from(first);

        for &index in remaining {
            let key = (u32::from(prefix) << 8) | u32::from(index);
            let (slot, entry) = scratch.lookup(key);
            if entry != 0 {
                prefix = (entry >> KEY_BITS) as u16;
                continue;
            }

            writer.code(prefix, width)?;
            width = next_width(width, next_code);

            if next_code == CODE_LIMIT {
                writer.code(clear, width)?;
                scratch.reset();
                width = depth + 1;
                next_code = clear + 2;
            } else {
                scratch.slots[slot] = (u32::from(next_code) << KEY_BITS) | key;
                next_code += 1;
            }
            prefix = u16::from(index);
        }

        writer.code(prefix, width)?;
        width = next_width(width, next_code);
    }

    writer.code(clear + 1, width)?;
    writer.finish()
}

// The decoder learns one entry when it reads the just-emitted data code.
// It starts using the wider width after that entry fills the old width.
fn next_width(width: u8, next_code: u16) -> u8 {
    width + u8::from(width < MAX_CODE_WIDTH && next_code == 1 << width)
}

struct SubBlocks<'a> {
    output: &'a mut [u8],
    written: usize,
    length_offset: usize,
    block_len: u8,
    pending: u32,
    pending_bits: u8,
}

impl<'a> SubBlocks<'a> {
    fn new(output: &'a mut [u8]) -> Self {
        Self {
            output,
            written: 0,
            length_offset: 0,
            block_len: 0,
            pending: 0,
            pending_bits: 0,
        }
    }

    fn byte(&mut self, value: u8) -> Result<(), LzwError> {
        let next = self
            .output
            .get_mut(self.written)
            .ok_or(LzwError::OutputTooSmall)?;
        *next = value;
        self.written += 1;
        Ok(())
    }

    fn payload_byte(&mut self, value: u8) -> Result<(), LzwError> {
        if self.block_len == 0 {
            self.length_offset = self.written;
            self.byte(0)?;
        }
        self.byte(value)?;
        self.block_len += 1;
        if self.block_len == BLOCK_LIMIT {
            self.output[self.length_offset] = self.block_len;
            self.block_len = 0;
        }
        Ok(())
    }

    fn code(&mut self, code: u16, width: u8) -> Result<(), LzwError> {
        debug_assert!(code < 1 << width);
        self.pending |= u32::from(code) << self.pending_bits;
        self.pending_bits += width;
        while self.pending_bits >= 8 {
            self.payload_byte(self.pending as u8)?;
            self.pending >>= 8;
            self.pending_bits -= 8;
        }
        Ok(())
    }

    fn finish(mut self) -> Result<usize, LzwError> {
        if self.pending_bits != 0 {
            self.payload_byte(self.pending as u8)?;
        }
        if self.block_len != 0 {
            self.output[self.length_offset] = self.block_len;
        }
        self.byte(0)?;
        Ok(self.written)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn encoded(indices: &[u8], depth: u8) -> Vec<u8> {
        let mut output = vec![0; indices.len() * 2 + 16];
        let mut scratch = LzwScratch::EMPTY;
        let count = encode_lzw(indices, depth, &mut output, &mut scratch).unwrap();
        output.truncate(count);
        output
    }

    fn unpack(blocks: &[u8]) -> (Vec<u8>, Vec<usize>) {
        let mut payload = Vec::new();
        let mut sizes = Vec::new();
        let mut remaining = &blocks[1..];
        loop {
            let (&size, bytes) = remaining.split_first().unwrap();
            if size == 0 {
                assert!(bytes.is_empty());
                return (payload, sizes);
            }
            let size = usize::from(size);
            assert!(size <= 254);
            payload.extend_from_slice(&bytes[..size]);
            sizes.push(size);
            remaining = &bytes[size..];
        }
    }

    fn decoded(blocks: &[u8]) -> (Vec<u8>, usize, usize) {
        let depth = usize::from(blocks[0]);
        let literal_count = 2_usize.pow(depth as u32);
        let (payload, _) = unpack(blocks);
        let mut offset = 0;
        let mut output = Vec::new();
        let mut table: Vec<Vec<u8>> = Vec::new();
        let mut previous: Option<Vec<u8>> = None;
        let mut width = depth + 1;
        let mut widest = width;
        let mut clears = 0;
        loop {
            let mut code = 0;
            for shift in 0..width {
                let bit = payload[offset / 8] >> (offset % 8) & 1;
                code |= usize::from(bit) << shift;
                offset += 1;
            }

            if code == literal_count {
                if clears != 0 {
                    assert_eq!(table.len(), 4096);
                }
                table = (0..literal_count)
                    .map(|literal| vec![literal as u8])
                    .collect();
                table.resize(literal_count + 2, Vec::new());
                previous = None;
                width = depth + 1;
                clears += 1;
                continue;
            }
            assert!(clears > 0, "first code must clear the dictionary");
            if code == literal_count + 1 {
                assert!(payload.len() * 8 - offset < 8, "bytes after end code");
                if offset % 8 != 0 {
                    assert_eq!(payload[offset / 8] >> (offset % 8), 0);
                }
                return (output, clears, widest);
            }

            let sequence = if code == table.len() {
                let mut sequence = previous.clone().unwrap();
                sequence.push(sequence[0]);
                sequence
            } else {
                table[code].clone()
            };
            assert!(!sequence.is_empty());
            output.extend_from_slice(&sequence);
            if let Some(mut entry) = previous {
                if table.len() < 4096 {
                    entry.push(sequence[0]);
                    table.push(entry);
                    if table.len() == 1 << width && width < 12 {
                        width += 1;
                        widest = widest.max(width);
                    }
                }
            }
            previous = Some(sequence);
        }
    }

    #[test]
    fn known_bytes_cover_empty_repetition_and_end_width_transition() {
        assert_eq!(encoded(&[], 2), [2, 1, 0x2c, 0]);
        assert_eq!(encoded(&[0], 2), [2, 2, 0x44, 0x01, 0]);
        assert_eq!(encoded(&[0, 0, 0], 2), [2, 2, 0x84, 0x0b, 0]);
        assert_eq!(encoded(&[0, 1, 2], 2), [2, 2, 0x44, 0x54, 0]);
    }

    #[test]
    fn sub_blocks_use_254_payload_bytes_at_the_boundary() {
        let indices: Vec<u8> = (0..224).collect();
        let exact = encoded(&indices[..223], 8);
        assert_eq!(unpack(&exact).1, [254]);
        assert_eq!(decoded(&exact).0, indices[..223]);
        let next = encoded(&indices, 8);
        assert_eq!(unpack(&next).1, [254, 1]);
        assert_eq!(decoded(&next).0, indices);
    }

    #[test]
    fn rejects_invalid_arguments_and_recovers_from_short_output() {
        let mut output = [238; 12];
        let mut scratch = LzwScratch::EMPTY;
        for depth in [0, 1, 9, 255] {
            assert_eq!(
                encode_lzw(&[1], depth, &mut output, &mut scratch),
                Err(LzwError::InvalidDepth)
            );
        }
        assert_eq!(
            encode_lzw(&[1, 4], 2, &mut output, &mut scratch),
            Err(LzwError::InvalidIndex)
        );
        assert_eq!(output, [238; 12]);
        for capacity in 0..5 {
            assert_eq!(
                encode_lzw(&[0, 1, 2], 2, &mut output[..capacity], &mut scratch),
                Err(LzwError::OutputTooSmall)
            );
        }
        assert_eq!(encode_lzw(&[0, 1, 2], 2, &mut output, &mut scratch), Ok(5));
        assert_eq!(&output[..5], &[2, 2, 0x44, 0x54, 0]);
        assert_eq!(&output[5..], &[238; 7]);
    }

    #[test]
    fn independent_decoder_round_trips_every_depth_through_dictionary_resets() {
        let mut seed = 0x23ac_af29_u32;
        for depth in 2..=8 {
            let indices: Vec<u8> = (0..50_000)
                .map(|_| {
                    seed ^= seed << 13;
                    seed ^= seed >> 17;
                    seed ^= seed << 5;
                    (seed >> (32 - depth)) as u8
                })
                .collect();
            let (pixels, clears, widest) = decoded(&encoded(&indices, depth));
            assert_eq!(widest, 12, "depth {depth}");
            assert!(clears > 1, "depth {depth}");
            assert_eq!(pixels, indices, "depth {depth}");
        }
    }
}

//! In-place mapping of prepared RGB pixels to GIF palette indices.

use crate::palette::nearest_index;

const CELL_COUNT: usize = 32 * 32 * 32;
const WORD_BITS: usize = u32::BITS as usize;
const MAX_PALETTE_BYTES: usize = 256 * 3;

/// Reusable cache. Initialize directly in caller-owned static memory with
/// `MapperScratch::EMPTY`.
pub struct MapperScratch {
    winners: [u8; CELL_COUNT],
    occupied: [u32; CELL_COUNT / WORD_BITS],
}

impl MapperScratch {
    pub const EMPTY: Self = Self {
        winners: [0; CELL_COUNT],
        occupied: [0; CELL_COUNT / WORD_BITS],
    };

    fn index(&mut self, rgb: [u8; 3], palette: &[u8]) -> u8 {
        let [red, green, blue] = rgb.map(|channel| usize::from(channel >> 3));
        let cell = (red << 10) | (green << 5) | blue;
        let word = &mut self.occupied[cell / WORD_BITS];
        let mask = 1 << (cell % WORD_BITS);
        if *word & mask == 0 {
            self.winners[cell] = nearest_index(rgb, palette);
            *word |= mask;
        }
        self.winners[cell]
    }
}

/// Maps a nonempty slice of complete RGBA pixels to 1 through 256 packed RGB
/// palette entries. Alpha is ignored. Each RGB555 cell uses the palette index
/// selected for the first prepared RGB pixel observed in that cell.
///
/// Success returns the pixel count. The first count bytes hold the mapped
/// indices, and the rest of the input buffer is untouched. Invalid RGBA or
/// palette length returns None before any bytes are written.
pub fn map_in_place(
    rgba: &mut [u8],
    packed_palette: &[u8],
    scratch: &mut MapperScratch,
) -> Option<usize> {
    if rgba.is_empty()
        || !rgba.len().is_multiple_of(4)
        || packed_palette.is_empty()
        || packed_palette.len() > MAX_PALETTE_BYTES
        || !packed_palette.len().is_multiple_of(3)
    {
        return None;
    }

    scratch.occupied.fill(0);
    let pixels = rgba.len() / 4;
    for index in 0..pixels {
        // The output index is at or before this pixel's RGBA start, so all
        // subsequent pixels are read from the original bytes.
        let [red, green, blue, _] = rgba.as_chunks::<4>().0[index];
        rgba[index] = scratch.index([red, green, blue], packed_palette);
    }
    Some(pixels)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn cache_uses_first_pixel_per_cell_and_resets_between_calls() {
        let palette = [0, 0, 0, 7, 7, 7, 255, 255, 255, 8, 0, 0];
        let first = [
            [0, 0, 0, 4],
            [7, 7, 7, 251],
            [8, 0, 0, 96],
            [255, 255, 255, 0],
            [248, 248, 248, 255],
        ];
        let second = [first[1], first[0], first[2], first[4], first[3]];
        let mut scratch = MapperScratch::EMPTY;
        let mut output = first;

        assert_eq!(
            map_in_place(output.as_flattened_mut(), &palette, &mut scratch),
            Some(5)
        );
        assert_eq!(&output.as_flattened()[..5], &[0, 0, 3, 2, 2]);
        assert_eq!(&output.as_flattened()[5..], &first.as_flattened()[5..]);

        output = second;
        assert_eq!(
            map_in_place(output.as_flattened_mut(), &palette, &mut scratch),
            Some(5)
        );
        assert_eq!(&output.as_flattened()[..5], &[1, 1, 3, 2, 2]);
        assert_eq!(&output.as_flattened()[5..], &second.as_flattened()[5..]);
    }

    #[test]
    fn greatest_tied_index_including_255_is_cacheable() {
        let mut input = [5, 7, 9, 0, 6, 7, 8, 255];
        let palette = [0; MAX_PALETTE_BYTES];
        let mut scratch = MapperScratch::EMPTY;
        assert_eq!(map_in_place(&mut input, &palette, &mut scratch), Some(2));
        assert_eq!(input, [255, 255, 9, 0, 6, 7, 8, 255]);
    }

    #[test]
    fn invalid_dimensions_and_palettes_leave_input_untouched() {
        let mut scratch = MapperScratch::EMPTY;
        let mut input = [170; 5];
        assert_eq!(map_in_place(&mut input, &[1, 2, 3], &mut scratch), None);
        assert_eq!(
            map_in_place(&mut input[..0], &[1, 2, 3], &mut scratch),
            None
        );
        for palette in [&[][..], &[1, 2][..], &[0; 257 * 3][..]] {
            assert_eq!(map_in_place(&mut input[..4], palette, &mut scratch), None);
        }
        assert_eq!(input, [170; 5]);
    }
}

//! Palette selection over the already prepared RGB pixels of one GIF frame.

const RED_DIM: usize = 33;
const GREEN_DIM: usize = 65;
const BLUE_DIM: usize = 33;
const STRIDES: [usize; 3] = [GREEN_DIM * BLUE_DIM, BLUE_DIM, 1];
const PREFIX_LEN: usize = RED_DIM * GREEN_DIM * BLUE_DIM;
const MAX_COLORS: usize = 256;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum PaletteMethod {
    Variance,
    WeightedMedian,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum PaletteError {
    InvalidLimit,
    InvalidInput,
    PixelCountOverflow,
    OutputTooSmall,
}

/// Caller-owned, reusable storage. Initialize directly in static storage with
/// `PaletteScratch::EMPTY` to keep the histogram off the stack.
pub struct PaletteScratch {
    prefix: Prefix,
    leaves: [Leaf; MAX_COLORS],
}

impl PaletteScratch {
    pub const EMPTY: Self = Self {
        prefix: Prefix {
            counts: [0; PREFIX_LEN],
            sums: [[0; 3]; PREFIX_LEN],
        },
        leaves: [Leaf::EMPTY; MAX_COLORS],
    };
}

/// Builds up to `limit` packed RGB entries and returns the number written.
///
/// The input must contain 1 through u32::MAX complete RGBA pixels. The caller
/// checks frame dimensions and prepares the pixels. Alpha is ignored. The
/// limit is 1 through 256 and output must hold at least limit * 3 bytes. Only
/// the returned number of entries is written. Errors leave output untouched.
///
/// Each RGB565 bin is indivisible, even when it contains several distinct
/// prepared colors. Each palette entry is the RGB888 mean of its leaf's
/// pixels, rounded to nearest with halves rounded up.
///
/// Variance first returns RGB888 means in lexicographic mapper-cell order
/// when all occupied RGB555 cells fit the limit. Otherwise, it selects the
/// RGB565 split with the highest population-weighted gain.
/// Scores use f64 arithmetic from integer moments. Equal computed scores
/// prefer red, green, then blue, and the lowest cut on the chosen axis.
/// Weighted median selects the longest occupied axis in RGB units and the cut
/// closest to a 50/50 population split. Axis and cut ties use the same order.
/// The most populous splittable leaf is selected for weighted median.
///
/// In both methods, the lowest leaf index wins equal selection priority. A
/// split replaces that slot with the lower child and appends the upper child.
/// Leaves are emitted in slot order.
pub fn build_palette(
    prepared_rgba: &[u8],
    limit: usize,
    output: &mut [u8],
    scratch: &mut PaletteScratch,
    method: PaletteMethod,
) -> Result<usize, PaletteError> {
    if !(1..=MAX_COLORS).contains(&limit) {
        return Err(PaletteError::InvalidLimit);
    }
    if prepared_rgba.is_empty() || !prepared_rgba.len().is_multiple_of(4) {
        return Err(PaletteError::InvalidInput);
    }
    if prepared_rgba.len() / 4 > u32::MAX as usize {
        return Err(PaletteError::PixelCountOverflow);
    }
    if output.len() < limit * 3 {
        return Err(PaletteError::OutputTooSmall);
    }

    let PaletteScratch { prefix, leaves } = scratch;
    prefix.populate(prepared_rgba);
    if method == PaletteMethod::Variance {
        if let Some(count) = prefix.mapper_centroids(limit, output) {
            return Ok(count);
        }
    }

    let (bounds, total) = prefix.accumulate();
    leaves[0] = Leaf::new(prefix, bounds, total, method, limit > 1);

    let mut count = 1;
    while count < limit {
        let Some((index, cut)) = next_split(&leaves[..count]) else {
            break;
        };

        let leaf = leaves[index];
        let mut lower_bounds = leaf.bounds;
        let mut upper_bounds = leaf.bounds;
        lower_bounds.high[cut.axis] = cut.boundary;
        upper_bounds.low[cut.axis] = cut.boundary;
        let search_children = count + 1 < limit;
        leaves[index] = Leaf::new(prefix, lower_bounds, cut.lower, method, search_children);
        leaves[count] = Leaf::new(
            prefix,
            upper_bounds,
            leaf.total.minus(cut.lower),
            method,
            search_children,
        );
        count += 1;
    }

    for (entry, leaf) in output
        .as_chunks_mut::<3>()
        .0
        .iter_mut()
        .zip(&leaves[..count])
    {
        *entry = leaf.total.rounded_mean();
    }
    Ok(count)
}

/// Returns the nearest entry in a palette of 1 through 256 packed RGB colors.
/// The greatest index wins ties in squared Euclidean RGB distance.
pub fn nearest_index(rgb: [u8; 3], palette: &[u8]) -> u8 {
    debug_assert!(!palette.is_empty() && palette.len().is_multiple_of(3));
    debug_assert!(palette.len() <= MAX_COLORS * 3);

    let [red, green, blue] = rgb.map(i32::from);
    let mut best_distance = i32::MAX;
    let mut best_index = 0;

    for (index, entry) in palette.as_chunks::<3>().0.iter().enumerate().rev() {
        let dr = red - i32::from(entry[0]);
        let dg = green - i32::from(entry[1]);
        let db = blue - i32::from(entry[2]);
        let distance = dr * dr + dg * dg + db * db;
        if distance == 0 {
            return index as u8;
        }
        if distance < best_distance {
            best_distance = distance;
            best_index = index as u8;
        }
    }
    best_index
}

#[derive(Clone, Copy)]
struct Moments {
    sums: [u64; 3],
    count: u32,
}

impl Moments {
    const ZERO: Self = Self {
        sums: [0; 3],
        count: 0,
    };

    fn plus(self, other: Self) -> Self {
        Self {
            sums: core::array::from_fn(|channel| self.sums[channel] + other.sums[channel]),
            count: self.count + other.count,
        }
    }

    fn minus(self, other: Self) -> Self {
        Self {
            sums: core::array::from_fn(|channel| self.sums[channel] - other.sums[channel]),
            count: self.count - other.count,
        }
    }

    fn rounded_mean(self) -> [u8; 3] {
        let count = u64::from(self.count);
        self.sums.map(|sum| ((sum + count / 2) / count) as u8)
    }
}

/// Coordinates are inclusive upper endpoints in the zero-padded prefix table.
/// A leaf contains bins after its lower endpoints through its upper endpoints.
#[derive(Clone, Copy)]
struct Bounds {
    low: [u8; 3],
    high: [u8; 3],
}

impl Bounds {
    const EMPTY: Self = Self {
        low: [0; 3],
        high: [0; 3],
    };
}

struct Prefix {
    counts: [u32; PREFIX_LEN],
    sums: [[u64; 3]; PREFIX_LEN],
}

impl Prefix {
    fn get(&self, index: usize) -> Moments {
        Moments {
            sums: self.sums[index],
            count: self.counts[index],
        }
    }

    fn put(&mut self, index: usize, moments: Moments) {
        self.sums[index] = moments.sums;
        self.counts[index] = moments.count;
    }

    fn populate(&mut self, prepared_rgba: &[u8]) {
        self.counts.fill(0);
        self.sums.fill([0; 3]);

        for rgba in prepared_rgba.as_chunks::<4>().0 {
            let red = usize::from(rgba[0] >> 3) + 1;
            let green = usize::from(rgba[1] >> 2) + 1;
            let blue = usize::from(rgba[2] >> 3) + 1;
            let index = red * STRIDES[0] + green * STRIDES[1] + blue;
            self.counts[index] += 1;
            let sums = &mut self.sums[index];
            sums[0] += u64::from(rgba[0]);
            sums[1] += u64::from(rgba[1]);
            sums[2] += u64::from(rgba[2]);
        }
    }

    fn mapper_centroids(&self, limit: usize, output: &mut [u8]) -> Option<usize> {
        let mut occupied_bins = [0; MAX_COLORS];
        let mut occupied = 0;
        for red in 1..RED_DIM {
            // Each five-bit green cell covers two adjacent RGB565 green bins.
            for green in (1..GREEN_DIM).step_by(2) {
                let row = red * STRIDES[0] + green * STRIDES[1];
                for blue in 1..BLUE_DIM {
                    let lower = row + blue;
                    let upper = lower + STRIDES[1];
                    if self.counts[lower] + self.counts[upper] == 0 {
                        continue;
                    }
                    if occupied == limit {
                        return None;
                    }
                    occupied_bins[occupied] = lower;
                    occupied += 1;
                }
            }
        }
        for (entry, &lower) in output
            .as_chunks_mut::<3>()
            .0
            .iter_mut()
            .zip(&occupied_bins[..occupied])
        {
            *entry = self
                .get(lower)
                .plus(self.get(lower + STRIDES[1]))
                .rounded_mean();
        }
        Some(occupied)
    }

    fn accumulate(&mut self) -> (Bounds, Moments) {
        let mut min = [RED_DIM as u8, GREEN_DIM as u8, BLUE_DIM as u8];
        let mut max = [0; 3];
        for red in 1..RED_DIM {
            let mut plane = [Moments::ZERO; BLUE_DIM];
            for green in 1..GREEN_DIM {
                let mut row = Moments::ZERO;
                let start = red * STRIDES[0] + green * STRIDES[1];
                for (blue, plane_sum) in plane.iter_mut().enumerate().skip(1) {
                    let index = start + blue;
                    let bin = self.get(index);
                    if bin.count != 0 {
                        let position = [red as u8, green as u8, blue as u8];
                        for axis in 0..3 {
                            min[axis] = min[axis].min(position[axis]);
                            max[axis] = max[axis].max(position[axis]);
                        }
                    }

                    row = row.plus(bin);
                    *plane_sum = plane_sum.plus(row);
                    self.put(index, plane_sum.plus(self.get(index - STRIDES[0])));
                }
            }
        }

        let bounds = Bounds {
            low: min.map(|value| value - 1),
            high: max,
        };
        (bounds, self.get(PREFIX_LEN - 1))
    }
}

/// Area at a fixed axis boundary, before subtracting the leaf's lower face.
/// The subtraction order keeps each count and channel sum nonnegative.
struct Plane {
    stride: usize,
    high_high: usize,
    low_high: usize,
    high_low: usize,
    low_low: usize,
}

impl Plane {
    fn new(bounds: Bounds, axis: usize) -> Self {
        let first = (axis + 1) % 3;
        let second = (axis + 2) % 3;
        let first_high = usize::from(bounds.high[first]) * STRIDES[first];
        let first_low = usize::from(bounds.low[first]) * STRIDES[first];
        let second_high = usize::from(bounds.high[second]) * STRIDES[second];
        let second_low = usize::from(bounds.low[second]) * STRIDES[second];

        Self {
            stride: STRIDES[axis],
            high_high: first_high + second_high,
            low_high: first_low + second_high,
            high_low: first_high + second_low,
            low_low: first_low + second_low,
        }
    }

    fn at(&self, prefix: &Prefix, boundary: u8) -> Moments {
        let base = usize::from(boundary) * self.stride;
        prefix
            .get(base + self.high_high)
            .minus(prefix.get(base + self.low_high))
            .minus(
                prefix
                    .get(base + self.high_low)
                    .minus(prefix.get(base + self.low_low)),
            )
    }
}

#[derive(Clone, Copy)]
struct Cut {
    lower: Moments,
    priority: f64,
    axis: usize,
    boundary: u8,
}

#[derive(Clone, Copy)]
struct Leaf {
    bounds: Bounds,
    total: Moments,
    cut: Option<Cut>,
}

impl Leaf {
    const EMPTY: Self = Self {
        bounds: Bounds::EMPTY,
        total: Moments::ZERO,
        cut: None,
    };

    fn new(
        prefix: &Prefix,
        bounds: Bounds,
        total: Moments,
        method: PaletteMethod,
        search: bool,
    ) -> Self {
        let cut = if search && total.count > 1 {
            best_cut(prefix, bounds, total, method)
        } else {
            None
        };
        Self { bounds, total, cut }
    }
}

fn next_split(leaves: &[Leaf]) -> Option<(usize, Cut)> {
    let mut best: Option<(usize, Cut)> = None;
    for (index, leaf) in leaves.iter().enumerate() {
        if let Some(cut) = leaf.cut {
            if best
                .as_ref()
                .is_none_or(|(_, current)| cut.priority > current.priority)
            {
                best = Some((index, cut));
            }
        }
    }
    best
}

fn best_cut(prefix: &Prefix, bounds: Bounds, total: Moments, method: PaletteMethod) -> Option<Cut> {
    let mut best: Option<Cut> = None;
    let mut longest_span = 0;

    for (axis, bin_width) in [8, 4, 8].into_iter().enumerate() {
        let plane = Plane::new(bounds, axis);
        let base = plane.at(prefix, bounds.low[axis]);
        let mut first_valid = 0;
        let mut last_valid = 0;
        let mut smallest_imbalance = u32::MAX;
        let mut median = None;

        for boundary in bounds.low[axis] + 1..bounds.high[axis] {
            let lower = plane.at(prefix, boundary).minus(base);
            if lower.count == 0 {
                continue;
            }
            if lower.count == total.count {
                break;
            }

            match method {
                PaletteMethod::Variance => {
                    let priority = variance_gain(lower, total.minus(lower));
                    if best
                        .as_ref()
                        .is_none_or(|current| priority > current.priority)
                    {
                        best = Some(Cut {
                            lower,
                            priority,
                            axis,
                            boundary,
                        });
                    }
                }
                PaletteMethod::WeightedMedian => {
                    if first_valid == 0 {
                        first_valid = boundary;
                    }
                    last_valid = boundary;
                    let imbalance = lower.count.abs_diff(total.count - lower.count);
                    if imbalance < smallest_imbalance {
                        smallest_imbalance = imbalance;
                        median = Some(Cut {
                            lower,
                            priority: f64::from(total.count),
                            axis,
                            boundary,
                        });
                    }
                }
            }
        }

        if first_valid != 0 {
            let span = (usize::from(last_valid - first_valid) + 1) * bin_width;
            if span > longest_span {
                longest_span = span;
                best = median;
            }
        }
    }

    best
}

fn variance_gain(lower: Moments, upper: Moments) -> f64 {
    let a = f64::from(lower.count);
    let b = f64::from(upper.count);

    // The distance between means is obtained by cross multiplication. Each
    // channel sum fits in 40 bits, and the denominator remains finite at
    // the maximum admitted population.
    let [dr, dg, db] = core::array::from_fn(|channel| {
        lower.sums[channel] as f64 * b - upper.sums[channel] as f64 * a
    });
    (dr * dr + dg * dg + db * db) / (a * b * (a + b))
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::sync::Mutex;

    static SCRATCH: Mutex<PaletteScratch> = Mutex::new(PaletteScratch::EMPTY);

    fn palette(input: &[[u8; 4]], limit: usize, method: PaletteMethod) -> Vec<[u8; 3]> {
        let mut output = vec![0; limit * 3];
        let count = build_palette(
            input.as_flattened(),
            limit,
            &mut output,
            &mut SCRATCH.lock().unwrap(),
            method,
        )
        .unwrap();
        output.as_chunks::<3>().0[..count].to_vec()
    }

    #[test]
    fn rejects_invalid_inputs_without_touching_output() {
        let rgba = [12, 34, 56, 78];
        let mut output = [194; 5];
        let mut scratch = SCRATCH.lock().unwrap();

        for (input, limit, expected) in [
            (&rgba[..], 0, PaletteError::InvalidLimit),
            (&rgba[..], 257, PaletteError::InvalidLimit),
            (&rgba[..0], 1, PaletteError::InvalidInput),
            (&rgba[..3], 1, PaletteError::InvalidInput),
            (&rgba[..], 2, PaletteError::OutputTooSmall),
        ] {
            assert_eq!(
                build_palette(
                    input,
                    limit,
                    &mut output,
                    &mut scratch,
                    PaletteMethod::Variance
                ),
                Err(expected)
            );
            assert_eq!(output, [194; 5]);
        }
        assert_eq!(
            build_palette(&rgba, 1, &mut output, &mut scratch, PaletteMethod::Variance),
            Ok(1)
        );
        assert_eq!(output, [12, 34, 56, 194, 194]);
    }

    #[test]
    fn rgb565_collision_uses_actual_bytes_and_rounds_half_up() {
        let pixels = [[144, 196, 8, 0], [151, 199, 15, 255]];
        for method in [PaletteMethod::Variance, PaletteMethod::WeightedMedian] {
            assert_eq!(palette(&pixels, 256, method), [[148, 198, 12]]);
            assert_eq!(palette(&[[255, 255, 255, 0]; 9], 256, method), [[255; 3]]);
            assert_eq!(palette(&[[0, 0, 0, 255]; 7], 256, method), [[0; 3]]);
        }
    }

    #[test]
    fn variance_and_median_make_different_population_tradeoffs() {
        let pixels = [
            [[0, 0, 0, 255]; 4].as_slice(),
            [[16, 0, 0, 255]; 10].as_slice(),
            [[255, 0, 0, 255]].as_slice(),
        ]
        .concat();

        assert_eq!(
            palette(&pixels, 2, PaletteMethod::Variance),
            [[11, 0, 0], [255, 0, 0]]
        );
        assert_eq!(
            palette(&pixels, 2, PaletteMethod::WeightedMedian),
            [[0, 0, 0], [38, 0, 0]]
        );
    }

    #[test]
    fn variance_prioritizes_gain_while_median_prioritizes_population() {
        let pixels = [
            [[0, 0, 0, 255]].as_slice(),
            [[24, 0, 0, 255]; 9].as_slice(),
            [[160, 0, 0, 255]; 6].as_slice(),
            [[252, 0, 0, 255]].as_slice(),
        ]
        .concat();

        assert_eq!(
            palette(&pixels, 3, PaletteMethod::Variance),
            [[22, 0, 0], [160, 0, 0], [252, 0, 0]]
        );
        assert_eq!(
            palette(&pixels, 3, PaletteMethod::WeightedMedian),
            [[0, 0, 0], [173, 0, 0], [24, 0, 0]]
        );
    }

    #[test]
    fn equal_gains_prefer_axis_cut_and_leaf_in_order() {
        let corners = [
            [0, 0, 0, 255],
            [0, 255, 0, 255],
            [255, 0, 0, 255],
            [255, 255, 0, 255],
        ];
        assert_eq!(
            palette(&corners, 2, PaletteMethod::Variance),
            [[0, 128, 0], [255, 128, 0]]
        );
        assert_eq!(
            palette(&corners, 3, PaletteMethod::Variance),
            [[0, 0, 0], [255, 128, 0], [0, 255, 0]]
        );

        let equally_spaced = [[0, 0, 0, 255], [16, 0, 0, 255], [32, 0, 0, 255]];
        for method in [PaletteMethod::Variance, PaletteMethod::WeightedMedian] {
            assert_eq!(palette(&equally_spaced, 2, method), [[0, 0, 0], [24, 0, 0]]);
        }
    }

    #[test]
    fn equivalent_rgb565_spans_prefer_red_for_weighted_median() {
        let corners = [
            [0, 0, 0, 255],
            [0, 248, 0, 255],
            [248, 0, 0, 255],
            [248, 248, 0, 255],
        ];
        assert_eq!(
            palette(&corners, 2, PaletteMethod::WeightedMedian),
            [[0, 124, 0], [248, 124, 0]]
        );
    }

    #[test]
    fn preserves_256_distinct_bins_and_is_independent_of_pixel_order() {
        let pixels: Vec<_> = (0..256)
            .map(|index| {
                [
                    ((index % 32) * 8 + 7) as u8,
                    (((index / 32) * 8 + index % 8) * 4 + 1) as u8,
                    ((index * 13 % 32) * 8 + 3) as u8,
                    255,
                ]
            })
            .collect();
        let mut expected: Vec<_> = pixels.iter().map(|&[r, g, b, _]| [r, g, b]).collect();
        expected.sort_unstable();
        let reversed: Vec<_> = pixels.iter().copied().rev().collect();

        for method in [PaletteMethod::Variance, PaletteMethod::WeightedMedian] {
            let mut output = palette(&pixels, 256, method);
            assert_eq!(output, palette(&reversed, 256, method));
            output.sort_unstable();
            assert_eq!(output, expected);
        }
    }

    #[test]
    fn sparse_variance_combines_adjacent_green_bins_and_orders_mapper_cells() {
        let pixels = [
            [32, 0, 224, 255],
            [32, 7, 231, 255],
            [32, 7, 231, 255],
            [0, 8, 0, 255],
            [0, 8, 7, 255],
            [0, 8, 0, 255],
            [0, 7, 24, 255],
        ];
        assert_eq!(
            palette(&pixels, 3, PaletteMethod::Variance),
            [[0, 7, 24], [0, 8, 2], [32, 5, 229]]
        );
        assert_eq!(
            palette(&pixels, 3, PaletteMethod::WeightedMedian),
            [[0, 8, 2], [0, 7, 24], [32, 5, 229]]
        );
    }

    #[test]
    fn moments_cover_maximum_population_and_channel_values() {
        let lower_count = u32::MAX / 2;
        let upper_count = u32::MAX - lower_count;
        let lower = Moments {
            sums: [0; 3],
            count: lower_count,
        };
        let upper = Moments {
            sums: [u64::from(upper_count) * 255; 3],
            count: upper_count,
        };
        let total = lower.plus(upper);

        assert_eq!(total.count, u32::MAX);
        assert_eq!(total.rounded_mean(), [128; 3]);
        assert_eq!(total.minus(lower).sums, upper.sums);
        let expected = (f64::from(lower_count) * f64::from(upper_count) / f64::from(u32::MAX))
            * (3.0 * 255.0 * 255.0);
        let relative_error = (variance_gain(lower, upper) - expected).abs() / expected;
        assert!(relative_error < 1e-15);
    }

    #[test]
    fn nearest_index_uses_all_channels_and_prefers_the_greatest_index_on_ties() {
        assert_eq!(nearest_index([10, 10, 10], &[8, 10, 10, 9, 9, 9]), 1);
        assert_eq!(
            nearest_index([10, 10, 10], &[10, 10, 9, 10, 11, 10, 12, 10, 10]),
            1
        );
        assert_eq!(nearest_index([255, 255, 255], &[0, 0, 0]), 0);
        assert_eq!(nearest_index([7, 8, 9], &[7, 8, 9, 0, 0, 0, 7, 8, 9]), 2);
        assert_eq!(nearest_index([0, 0, 0], &[0; 256 * 3]), 255);
    }
}

